		'ft3q' => 'هل يمكن لشركة تجارية تقديم أجهزة قياس OEM بعلامتي التجارية؟',
		'ft3a' => 'عادةً لا عمليًا. العمل بعلامة OEM — طباعة شعارك وتغليف مخصص وتغيير المدى — أمر روتيني للمصنع لأنه يتحكم في خط الإنتاج والقوالب. شركة تجارية لا تستطيع عادةً إجراء تغييرات لأن المصنع خلفها لن يتعاون.',
		'ft4q' => 'ما الشهادات التي يجب أن يقدمها مورّد مصنع لأجهزة القياس؟',
		'ft4a' => 'CE (EMC · LVD) وRoHS هي الأساس، ويفضَّل ضمن نظام إدارة جودة ISO 9001. اطلب مستندات الشهادة وتحقق من رقمها لدى الجهة المانحة قبل الطلب بكميات كبيرة.',
		'cr1q' => 'ماذا يعني تصنيف CAT على جهاز القياس في الواقع؟',
		'cr1a' => 'يصف تصنيف فئة القياس (CAT) وفق IEC 61010 مقدار الجهد الزائد العابر الذي يمكن للجهاز تحمّله عند توصيله بدائرة من تلك الفئة. التصنيف الأعلى — CAT IV هو الأعلى — يعني أن الجهاز مصمم لتحمّل عابرات أكبر بأمان.',
		'cr2q' => 'ما الفرق بين CAT II وCAT III وCAT IV؟',
		'cr2a' => 'يغطي CAT II الدوائر الموصولة بمأخذ الحائط، مثل الأجهزة والأدوات. يغطي CAT III أعمال مستوى التوزيع — اللوحات والتحكم بالمحركات والأسلاك الثابتة — حيث يحدث معظم الأعمال الصناعية والصيانة. CAT IV هو نقطة دخول الشبكة إلى المبنى، مع أعلى تعرض للعابرات.',
		'cr3q' => 'هل يمكنني استخدام جهاز CAT II على لوحة توزيع؟',
		'cr3a' => 'تقنيًا سيقيس الجهاز، لكنك ستستخدمه خارج فئة الأمان التصميمية له. اللوحات والتحكم بالمحركات بيئات CAT III، لذلك اختر جهازًا بتصنيف CAT III 600 فولت أو أعلى مع حماية إدخال لهذا العمل.',
		'cr4q' => 'كيف أتحقق من أن تصنيف CAT للجهاز حقيقي؟',
		'cr4a' => 'اطلب من المصنع تقرير اختبار IEC 61010 ووثائق CE EMC/LVD خلف التصنيف. التصنيفات المبالغ فيها أو غير المختبرة من أكثر عيوب الواردات الرخيصة شيوعًا، لذلك اشترِ من مصنع يمكنه توثيق المطابقة.',
		'cc1q' => 'هل أحتاج إلى جهاز قياس بمشبك AC/DC أم يكفي مشبك AC فقط؟',
		'cc1a' => 'لمعظم أعمال توزيع الطاقة — أحمال المحركات والسخانات والمغذيات — يكفي مشبك AC فقط. إذا كنت تقيس تيارًا مستمرًا — منشآت شمسية أو سيارات أو أنظمة بطاريات أو محركات DC — اختر طرازًا بمشبك AC/DC ومستشعر تأثير هول. مجموعتنا من أجهزة القياس بالمشبك تشمل النوعين.',
		'cc2q' => 'ما هو True RMS وهل أحتاجه في جهاز القياس بالمشبك؟',
		'cc2a' => 'على الأحمال الجيبية النظيفة تقرأ الأجهزة ذات الاستجابة المتوسطة وTrue RMS نفس القراءة. على المعدات الحديثة — محولات التردد وإمدادات الطاقة التبديلية والصابورات الإلكترونية — قد يقرأ الجهاز ذو الاستجابة المتوسطة أقل. نماذج True RMS تحسب القيمة الحرارية الفعلية للموجة وهي الخيار الصحيح للمشترين الصناعيين والتجاريين.',
		'cc3q' => 'ما حجم فكّة المشبك الذي أحتاجه؟',
		'cc3a' => 'يجب أن تفتح الفكّة بما يكفي لاستيعاب الموصل. النماذج ذات الفكة الصغيرة تناسب اللوحات وخزائن التحكم؛ والفكات الأكبر (40 ملم فأكثر) للكابلات السميكة وقضبان التوصيل. إذا كان عملاؤك يعملون على مولدات ومعدات ثقيلة، فضّل سعة الفكة على قابلية النقل.',
		'cc4q' => 'هل يمكنني تخزين أجهزة قياس بمشبك بعلامتي الخاصة؟',
		'cc4a' => 'نعم. السلاسل الشائعة مثل XT2017 وVC3268 وسلسلتا VC3269 / VC3270 متوفرة بعلامتك التجارية ضمن برنامج OEM، مع مشبك AC مضغوط ومشبك AC/DC وطراز صناعي بفكة كبيرة كمزيج نموذجي للموزعين.',
		'sy1q' => 'ماذا يعني رمز V~ على جهاز القياس؟',
		'sy1a' => 'V~ هو الجهد المتردد AC وV⎓ هو الجهد المستمر DC. اضبط المفتاح الدوار على الرمز المطابق للإشارة التي تقيسها — معظم الأجهزة لديها أيضًا وضع mV لأعمال الحساسات منخفضة الجهد. انقل سلك الاختبار إلى المقبس الصحيح أولًا.',
		'sy2q' => 'ماذا يعني رمز الاستمرارية ))) على جهاز القياس؟',
		'sy2a' => 'رمز الاستمرارية (يُعرض غالبًا كـ ))) ) يصدر صوت طنين عند إغلاق الدائرة، لتتبع الأسلاك والتأكد من سلامة الدائرة دون قراءة أرقام. إنها أسرع طريقة للعثور على مسار مفتوح أو قصير.',
		'sy3q' => 'لماذا يظهر جهاز القياس الرقم 1 على يسار الشاشة؟',
		'sy3a' => 'الرقم «1» على اليسار هو مؤشر التحميل الزائد / الخروج عن المدى. يعني أن القراءة تتجاوز المدى الحالي — بدّل إلى مدى أعلى، أو مع الأجهزة ذات المدى التلقائي أعد تحديد الوظيفة. في وضع المقاومة يعني عادةً دائرة مفتوحة.',
		'sy4q' => 'هل تشمل أجهزة CHINYOO رمز درجة حرارة؟',
		'sy4a' => 'بعض النماذج نعم. جهاز DT700C الجيبي، على سبيل المثال، يقيس درجة الحرارة من −20 °C إلى 1000 °C بمسبار حرارة مزدوجة، ويظهر على المفتاح الدوار بوضع °C. راجع مواصفات كل طراز للوظائف المتوفرة.',
		'mf1q' => 'كيف أعرف ما إذا كان مورّد أجهزة القياس الصيني مصنعًا أم شركة تجارية؟',
		'mf1a' => 'اطلب عنوان الإنتاج وتحقق منه على الخريطة، واطلب صورًا حديثة أو مكالمة فيديو للخط، وتحدث عن مواصفات حقيقية، وتحقق من الشهادات لدى الجهات المانحة، واطلب تعديلًا صغيرًا مخصصًا. المصنع يستطيع إظهار الإنتاج والاستجابة للتعديلات؛ الشركة التجارية عادةً لا تستطيع.',
		'mf2q' => 'ما هو الحد الأدنى الواقعي لطلبات أجهزة القياس OEM؟',
		'mf2a' => 'يعتمد الحد الأدنى على الطراز ومستوى التخصيص. النماذج القياسية المتوفرة أكثر مرونة وغالبًا ما تُطلب بكميات تجريبية صغيرة؛ النسخ OEM بعلامة وتغليف مخصصين تحمل حدًا أدنى أعلى. أخبرنا بالطراز المستهدف والكمية وسنقدم عرضًا.',
		'mf3q' => 'ما الذي يجب التحقق منه قبل تقديم طلب أجهزة قياس بالجملة؟',
		'mf3a' => 'نفّذ القائمة: قاعدة الإنتاج، الشهادات (CE EMC/LVD وRoHS وISO 9001)، خيارات التخصيص وحدودها الدنيا، مراقبة الجودة — كم وحدة تُختبر لكل دفعة، ضمان مكتوب 12 شهرًا، وطلب عينة قبل الالتزام بحاوية.',
		'mf4q' => 'كم يستغرق طلب OEM من العينة إلى الشحن؟',
		'mf4a' => 'بعد الموافقة على العينة، تعتمد مدة الإنتاج على حجم الطلب ودرجة التخصيص. الإعدادات القياسية تُشحن أسرع؛ العلامة والتغليف المخصصان يضيفان وقتًا قليلًا. اسأل فريق المبيعات وسنقدم لك جدولًا زمنيًا لطلبك المحدد.',
		'mmh1q' => 'ما هي الطريقة الأكثر أمانًا لقياس الجهد المتردد بالمقياس المتعدد؟',
		'mmh1a' => 'اضبط المفتاح الدوار على وضع الجهد المتردد، وأدخل السلك الأسود في منفذ COM والأحمر في منفذ الجهد، واختر مدىً أعلى من الجهد المتوقع، ثم المس المجسين بالأطراف. ولا تبدّل وضع المفتاح الدوار أبدًا بينما المجسان على دائرة حيّة.',
		'mmh2q' => 'لماذا يعرض مقياسي المتعدد الرقم 1 على يسار الشاشة؟',
		'mmh2a' => 'الرقم «1» على اليسار هو مؤشر الخروج عن المدى. ويعني أن القراءة أعلى من المدى المحدد، فبدّل إلى مدى أعلى بدلًا من افتراض أن القيمة حقيقية.',
		'mmh3q' => 'هل يمكنني قياس التيار بمقياس متعدد عادي؟',
		'mmh3a' => 'نعم، لكن يجب توصيل الجهاز على التوالي مع الحمل، وهو ما يعني فتح الدائرة. أما لقياس التيار في المحركات واللوحات الحيّة، فمقياس المشبك أكثر أمانًا وأسرع، لأن فكّته تحيط بالموصل دون قطع أي شيء.',
		'mmh4q' => 'أي مقياس متعدد هو الأفضل للمبتدئين؟',
		'mmh4a' => 'مقياس أساسي مثل سلسلة DT830 يغطي فحوصات الجهد والمقاومة والاستمرارية لمعظم الأعمال المنزلية. وإذا كنت تتعامل مع دوائر حيّة، فاختر جهازًا بتصنيف أمان CAT وتعلّم استخدام مقياس المشبك لقياس التيار.',
		'irg1q' => 'ما الذي يقيسه مقياس الحرارة بالأشعة تحت الحمراء فعليًا؟',
		'irg1a' => 'يقيس درجة حرارة سطح ما هو داخل بقعة القياس، لا الهواء ولا باطن الجسم. لذلك فإن المسافة وحجم البقعة والانبعاثية (emissivity) كلها تغيّر القراءة.',
		'irg2q' => 'لماذا يقرأ مقياس الحرارة بالأشعة تحت الحمراء قراءة منخفضة على المعادن؟',
		'irg2a' => 'يعكس المعدن المصقول حرارة المحيط بدلًا من إشعاعها بشكل متوقع. ضع قطعة شريط أسود أو طلاءً غير لامع على الهدف وصوّب نحوها للحصول على قراءة موثوقة.',
		'irg3q' => 'ما هي نسبة المسافة إلى بقعة القياس؟',
		'irg3a' => 'تصف كيف تكبر بقعة القياس مع زيادة المسافة. عند نسبة 12:1، يُقاس هدف يبعد 12 بوصة عبر دائرة يبلغ قطرها بوصة واحدة تقريبًا. اعمل عن قرب وأبقِ الزناد مضغوطًا حتى تستقر القراءة.',
		'irg4q' => 'ما أجهزة قياس درجة الحرارة التي تقدمها CHINYOO؟',
		'irg4a' => 'إضافةً إلى طرازات الأشعة تحت الحمراء للفحص السريع، يصنع المصنع مقاييس حرارة متعددة القنوات مع مجسات، ومقاييس حرارة ورطوبة، وأجهزة اختبار حرارة للاستخدام على اللوحات ومقاعد العمل. تواصل معنا لمعرفة التشكيلة الحالية.',
		'otg1q' => 'ما الذي يكتشفه جهاز اختبار المقبس؟',
		'otg1a' => 'يُوصّل بمقبس التيار المتردد ويقرأ نمط أضواء LED للتحقق من التوصيل الصحيح، وانعكاس القطبية، والأرضي المفتوح، والنيوترال المفتوح، والأسلاك المتقاطعة في ثوانٍ.',
		'otg2q' => 'كيف أستخدم جهاز اختبار المقبس؟',
		'otg2a' => 'أدخله في المقبس، واقرأ نمط أضواء LED، وقارنه بمفتاح الرموز المطبوع على الجهاز. واضغط زر اختبار قاطع التسرب الأرضي (GFCI) للتأكد من أن جهاز الأمان يفصل ثم يعود.',
		'otg3q' => 'هل أحتاج إلى كهربائي إذا أظهر الجهاز وجود عطل؟',
		'otg3a' => 'نعم. إذا كان النمط غير التوصيل الصحيح، فتوقف عن استخدام ذلك المقبس واطلب من كهربائي مؤهل إصلاحه، خاصة في أعطال الأرضي أو القطبية.',
		'otg4q' => 'هل يغني جهاز اختبار المقبس عن المقياس المتعدد؟',
		'otg4a' => 'لفحص التوصيلات، هو أسرع ولا يحتاج مهارة لقراءته. أما المقياس المتعدد فيعطي الجهد الفعلي وتفاصيل أكثر، لذلك يحمل كثير من الفنيين الاثنين معًا.',
		'hv1q' => 'ما أهم مدى في المقياس المتعدد لأعمال التدفئة والتهوية وتكييف الهواء (HVAC)؟',
		'hv1a' => 'السعة. مكثّف التشغيل أو الإقلاع الضعيف هو السبب وراء كثير من بلاغات «المحرك يطنّ لكنه لا يعمل»، وجهاز بمدى ميكروفاراد (uF) يفحصه في ثوانٍ. والجهد والاستمرارية ودرجة الحرارة مهمة أيضًا.',
		'hv2q' => 'هل أحتاج إلى true-RMS لأعمال HVAC؟',
		'hv2a' => 'نعم، إذا كنت تتعامل مع محركات متغيرة السرعة وضواغط إنفرتر، حيث تقرأ الأجهزة ذات الاستجابة المتوسطة قراءات منخفضة على الموجات غير الجيبية. أما true-RMS فيعطي قراءات دقيقة على المعدات الحديثة.',
		'hv3q' => 'ما تصنيف CAT الذي أحتاجه لأعمال HVAC؟',
		'hv3a' => 'CAT III 600 فولت هو الحد الأدنى للعمل، لأن صيانة أنظمة HVAC تتم عند اللوحة والقاطع والضاغط، حيث تكون الطاقة العابرة عالية.',
		'hv4q' => 'هل يمكن لجهاز واحد أن يغطي الجهد والسعة ودرجة الحرارة؟',
		'hv4a' => 'نعم. مقياس متعدد بمدى سعة ومدخل مجس حرارة يغطي القياسات اليومية لأنظمة HVAC في أداة واحدة. وتصنع CHINYOO أيضًا أجهزة حرارة منفصلة إن كنت تفضّل ذلك.',
		'ch1q' => 'لماذا يقرأ مقياس المشبك صفرًا على كابل؟',
		'ch1a' => 'لأنك أحطت بالفكّين بموصلي كابل ثنائي النواة معًا، فألغى التيارُ الخارجُ والتيارُ العائدُ أحدهما الآخر. يجب أن تحيط الفكّة بالموصل الحيّ الواحد فقط.',
		'ch2q' => 'هل يمكن لمقياس المشبك قياس التيار المستمر؟',
		'ch2a' => 'فقط مقياس المشبك AC+DC المزود بمستشعر تأثير هول. فالنماذج القياسية التي تقيس AC فقط لا تقيس إلا التيار المتردد. أما VC3269 وVC3270 فيقيسان التيارين المتردد والمستمر معًا.',
		'ch3q' => 'ما هو تيار الإقلاع (الاندفاع) ولماذا هو مهم؟',
		'ch3a' => 'عند إقلاع المحرك، يسحب نبضة تيار أعلى بعدة أضعاف من تيار تشغيله لجزء من الثانية. وتلك النبضة تفصل القواطع، ومقياس المشبك المزود بوظيفة التقاط تيار الإقلاع يظهر الذروة.',
		'ch4q' => 'أيهما أفضل: مقياس المشبك أم المقياس المتعدد؟',
		'ch4a' => 'لقياس التيار في المحركات واللوحات الحيّة، مقياس المشبك أكثر أمانًا وأسرع. أما للجهد والمقاومة والعمل الدقيق، فالمقياس المتعدد أدق. ومعظم الفنيين يحملون الاثنين معًا.',
		'd8301q' => 'لماذا يُستخدم المقياس الرقمي المتعدد DT830؟',
		'd8301a' => 'يقيس جهد التيار المستمر والمتردد، والمقاومة، والاستمرارية، وهبوط جهد الدايود، لفحوصات المنزل والصناعة الخفيفة. إنه المقياس الاقتصادي الذي يغطي معظم أعمال استكشاف الأعطال الأساسية.',
		'd8302q' => 'ما الفرق بين DT830B وDT830D؟',
		'd8302a' => 'يشتركان في الهيكل والمفتاح الدوار نفسهما. يضيف DT830D جرس استمرارية ومقبس اختبار الترانزستور، ولهذا يفضّل الموزعون اعتماده كخيار افتراضي.',
		'd8303q' => 'هل دقة DT830 كافية للأعمال الاحترافية؟',
		'd8303a' => 'نعم، لفحوصات الجهد والاستمرارية والمقاومة الأساسية. لكنه لا يدعم true-RMS وعدد عدّاته منخفض، لذا لدوائر الإنفرتر أو القياسات الدقيقة اختر طرازًا بعدّات أعلى.',
		'd8304q' => 'هل يمكنني شراء سلسلة DT830 بالجملة بعلامتي التجارية؟',
		'd8304a' => 'نعم — CHINYOO هي المصنع. نورد سلسلة DT830 للجملة وبرامج OEM/ODM بعلامة مخصصة وتغليف ووثائق CE/RoHS.',
		'vtvm1q' => 'هل جهاز اختبار الجهد أفضل من جهاز القياس المتعدد؟',
		'vtvm1a' => 'لا يُعد أي منهما أفضل بشكل مطلق؛ فكل واحد يجيب عن سؤال مختلف. جهاز اختبار الجهد يعطي إجابة سريعة بنعم أو لا عن «هل هناك تيار؟». أما المقياس المتعدد فيعطي القيم الفعلية للجهد والتيار والمقاومة واتصال الدائرة. احتفظ بالجهاز لفحوصات السلامة السريعة وبالمقياس للتشخيص.',
		'vtvm2q' => 'هل يمكن لجهاز اختبار الجهد أن يحل محل جهاز القياس المتعدد؟',
		'vtvm2a' => 'للفحوصات الوجودية، نعم. لقياس القيم الدقيقة، لا. الجهاز يخبرك أن التيار موجود، والمقياس يخبرك أن القراءة 3.8 فولت في حين يجب أن تكون 5، وهكذا تُكتشف معظم الأعطال.',
		'vtvm3q' => 'متى أستخدم جهاز اختبار الجهد غير التلامسي؟',
		'vtvm3a' => 'استخدمه للفحص السريع «هل هناك تيار؟» قبل لمس سلك أو مقبس، ولتحديد الموضع الذي يتوقف عنده التيار، ولتمييز السلك الحي من المحايد. يعمل دون لمس الموصل، لذا فهو سريع وآمن من مسافة.',
		'vtvm4q' => 'أي جهاز أشتري أولاً: جهاز الاختبار أم المقياس؟',
		'vtvm4a' => 'إذا كان عملك قائماً على فحوصات السلامة والتأكد من انقطاع التيار، فابدأ بجهاز الاختبار. أما إذا كنت تشخّص أو تقيس أو تصلح، فابدأ بالمقياس. معظم الفنيين يقتنون الاثنين في النهاية. قلم VD06 وجهاز DT700 يغطيان هذا الثنائي.',
		'amm1q' => 'ما أفضل مقياس متعدد لأعمال السيارات؟',
		'amm1a' => 'جهاز يغطي على الأقل جهد التيار المستمر واتصال الدائرة والمقاومة، مع شاشة مضيئة ونطاق تلقائي. لأعمال المحركات الحديثة أضف دورة التشغيل وعدد الدورات. لمعظم أعمال الهواة، يكفي جهاز مدمج مثل سلسلة DT700 لفحص البطارية والمنصهرات والمولد.',
		'amm2q' => 'ما الجهد الذي يجب أن تظهره بطارية السيارة على المقياس؟',
		'amm2a' => 'مع إيقاف المحرك، تقرأ البطارية السليمة نحو 12.6 فولت في وضع السكون. دون 12.4 فولت تكون منخفضة، ودون 12.0 فولت تكون مفرغة. ومع تشغيل المحرك، يجب أن يشحن المولد بين 13.5 و14.5 فولت.',
		'amm3q' => 'هل يمكنني استخدام مقياس متعدد عادي في السيارة بدل قلم الفحص؟',
		'amm3a' => 'نعم. المقياس الرقمي المتعدد يقيس جهد البطارية وإخراج المولد واتصال المنصهرات ومقاومة الحساسات. أما قلم فحص السيارات فهو أسرع لتتبع القدرة والأرضي في دوائر 12/24 فولت. نحن نورد الاثنين.',
		'amm4q' => 'هل أحتاج مقياساً متعدداً مخصصاً للسيارات؟',
		'amm4a' => 'ليس بالضرورة. مقياس رقمي عام بمدى مناسب يعمل مع سيارة 12 فولت. الطرازات المخصصة للسيارات تضيف دورة التشغيل وعدد الدورات ودرجة الحرارة لأعمال الحاقن والإشعال. اختر الوظائف حسب أعمالك الفعلية.',
		'ind1q' => 'نخزّن أجهزة اختبار الجهد للكهربائيين وفرق الصيانة. هل يستحق 1881 الاحتفاظ به كجهاز مضغوط واحد يغطي عدة مهام؟',
		'ind1a' => 'نعم، إن 1881 قلم رقمي لاختبار الجهد بشاشة LCD ومصباح طور نيون، يضم عدة أوضاع كشف خلف زر اختبار واحد. في الكشف المباشر يقرأ الجهد الفعلي عبر نطاق 12V إلى 220V تيار متناوب ومستمر، كما يستشعر الأسلاك الموصولة دون لمس المعدن ويكتشف انقطاعات الأسلاك المخفية. لعملائك، قلم مضغوط واحد يغطي مهام كانت تتطلب عدة أدوات.',
		'ind2q' => 'عملاؤنا يتتبعون أعطال الأسلاك ويضيعون الوقت في الانقطاعات المخفية. هل يجد 1881 السلك المقطوع دون فتح الكابل؟',
		'ind2a' => 'نعم. في وضع كشف نقطة الانقطاع، يُمرَّر طرف 1881 على طول الموصل المشحون، وتبقى الشاشة مضاءة ما دام السلك سليمًا. وعند نقطة الانقطاع المخفي يتوقف الإشارة، فيحصل عميلك على موقع مؤكد للقص والإصلاح بدلًا من فتح مسار كابل كامل. وهذا توفير حقيقي للوقت للكهربائيين الذين يعملون على منشآت قائمة.',
		'ind3q' => 'تتطلب فحوصات السلامة لدينا التأكد من أن السلك غير مشحون قبل أن يعمل عليه الفني. هل يمكن لـ 1881 تأكيد ذلك دون لمس المعدن؟',
		'ind3a' => 'نعم. في وضع الاستشعار الحثّي، يقرأ 1881 المجال الكهربائي حول الموصل عبر العازل، فيؤكد أن السلك مشحون دون أي تلامس مع المعدن. وهذا مفيد لتتبع الكابلات خلف العوازل أو للتحقق من أن الدائرة غير مشحونة فعلًا قبل بدء العمل. طرف القلم والفحص غير التلامسي يتيحان لفريقك البقاء على مسافة آمنة.',
		'ind4q' => 'هل يمكنني طلب عينات أو OEM أو كميات كبيرة من 1881؟',
		'ind4a' => 'نعم. ندعم طلبات العينات للتقييم، وOEM والعلامة الخاصة بعلامتك التجارية على 1881، والطلبات الكبيرة بأسعار مباشرة من المصنع. تعتمد مدة التسليم على الكمية والتخصيص، ونؤكدها عند إرسال استفسارك. أخبرنا بسوقك المستهدف وحجم الطلب وسيقوم فريق المصنع بعرض السعر المناسب.',
		'dt9205q1q' => 'ما الذي يمكن أن يقيسه DT9205A ولا يمكن لمقياس أساسي من فئة 830؟',
		'dt9205q1a' => 'يضيف DT9205A مدى سعة من 20 نانو فاراد إلى 200 ميكرو فاراد، ومسار تيار 20 أمبير للتيارين المستمر والمتردد، ومقبس كسب الترانزستور hFE، على شاشة 1999 عدّة نفسها التي يستخدمها المقياس الأساسي. هذه المديات الثلاثة هي بالضبط ما يميزه عن فئة 830 في الإلكترونيات وإصلاح المنضدة.',
		'dt9205q2q' => 'ما دقة DT9205A؟',
		'dt9205q2a' => 'جهد التيار المستمر مقنَّن بـ ±1.5%، والمتردد بـ ±1.8%، والمقاومة بـ ±2.0% على المديات المفيدة، مع مدى 200 ميجا أوم عند ±7.0%. كل وحدة تمر عبر منصة المعايرة نفسها في مصنعنا في ونزو قبل التغليف.',
		'dt9205q3q' => 'كيف أقيس مكثفًا بأمان باستخدام DT9205A؟',
		'dt9205q3a' => 'فرّغ المكثف أولًا، ويفضَّل بربط الطرفين بمقاومة مصنّفة لجهد الشحن المخزن، ثم اختر مدى السعة اليدوي القريب من القيمة المتوقعة واقرأ. المكثف الذي يقرأ أقل بكثير من قيمته المطبوعة أو يظهر مفتوحًا يجب استبداله.',
		'dt9205q4q' => 'هل يمكنني شراء DT9205A بالجملة أو بعلامتي التجارية؟',
		'dt9205q4a' => 'نعم — CHINYOO هي المصنع. نورد DT9205A للجملة وبرامج OEM/ODM بعلامة مخصصة وتغليف ووثائق CE/RoHS. أرسل لنا الكمية المستهدفة لعرض سعر.',
		'vc3268q1q' => 'ماذا يمكن أن يقيس VC3268 بالإضافة إلى تيار المتردد بالمشبك؟',
		'vc3268q1a' => 'VC3268 ملقط بشاشة 4000 خانة يقيس أيضاً الجهد المستمر والجهد المتردد والتيار المستمر بالمشبك والمقاومة والتردد حتى 4 ميجاهرتز والسعة حتى 4 ميكروفاراد، مع فحص الديود والاستمرارية. هو ملتيميتر مضغوط حول المشبك، لا ملقط للتيار المتردد فقط.',
		'vc3268q2q' => 'هل يستطيع VC3268 قياس التيار المستمر؟',
		'vc3268q2a' => 'نعم. وضع التيار المستمر يقرأ التيار على مدى المشبك 40 أمبير و400 أمبير نفسه، فيغطي سلاسل الإنفرتر الشمسي ودوائر البطاريات واللوحات التي تعمل بالتيار المستمر إلى جانب أحمال المحركات المترددة.',
		'vc3268q3q' => 'هل يخزّن الموزّع VC3268 أم سلسلة 266 أم VC3270؟',
		'vc3268q3a' => 'الثلاثة تغطي ثلاث فئات. VC3268 هو الخيار المضغوط الشامل بشاشة 4000 خانة للوحات والأعمال الصناعية الخفيفة. سلسلة 266 تصل إلى 1000 أمبير للطرف الصناعي، وVC3270 يضيف فكّين كبيرين للخطوط السميكة والقضبان. معظم الموزّعين يبدؤون بـ VC3268 ويضيفون الآخرين حسب القناة.',
		'vc3268q4q' => 'هل أستطيع شراء VC3268 بالجملة أو بعلامتي الخاصة؟',
		'vc3268q4a' => 'نعم — CHINYOO هو المصنع في ونتشو. نوفر VC3268 للبيع بالجملة وبرامج OEM/ODM بعلامتك التجارية وتغليفك ووثائق CE/RoHS. أرسل لنا الكمية المستهدفة لنرسل لك السعر.',
		'a8301q' => 'ماذا يمكن أن يقيس الملتيميتر الرقمي A830L؟',
		'a8301a' => 'جهد تيار مستمر حتى 500 فولت (±1.5%)، وجهد تيار متردد على مدى 200 و500 فولت (±3.0%)، وتيار مستمر من 2 مللي أمبير حتى 10 أمبير، ومقاومة حتى 2 ميجا أوم (±2.0%)، بالإضافة إلى فحص الديود وصفارة الاستمرارية واختبار بطارية 1.5 فولت مخصص لا تحمله بقية عائلة 830.',
		'a8302q' => 'ما الذي يميز A830L عن بقية الملتيمترات الاقتصادية؟',
		'a8302a' => 'يضيف اختبار بطارية 1.5 فولت كوضع على القرص، وإضاءة خلفية للعمل في الإضاءة الخافتة، وقفل قراءة لتثبيت القياس، وهي ميزات تُحجز عادةً للأجهزة الأغلى. على شاشة 1999 خانة، هذه الإضافات الثلاث هي ما يميزه على رف الملتيمترات الاقتصادية.',
		'a8303q' => 'هل يستطيع A830L اختبار بطارية 9 فولت؟',
		'a8303a' => 'وضع البطارية المخصص مصمم لخلايا 1.5 فولت (AA وAAA). لبطارية 9 فولت في جهاز إنذار الدخان، بدّل إلى مدى جهد التيار المستمر واقرأ القيمة مباشرة. البطاريات القابلة لإعادة الشحن يجب فحصها حسب كيميائها أولًا، لأن الاختبار مصمم لبطاريات القلوية الشائعة.',
		'a8304q' => 'هل أستطيع شراء A830L بالجملة أو بعلامتي الخاصة؟',
		'a8304a' => 'نعم — CHINYOO هو المصنع في ونتشو. نوفر A830L للبيع بالجملة وبرامج OEM/ODM بعلامتك التجارية وتغليفك ووثائق CE/RoHS، مع نفس ضمان 12 شهرًا لبقية التشكيلة. أرسل الكمية المستهدفة لنرسل لك السعر.',
		'pen1q' => 'ماذا يكتشف قلم الاختبار 88-2؟',
		'pen1a' => 'يخبرك هل الموصل مشحون أم لا، ويعرض قيمة الجهد على شاشته الرقمية. مصنوع وفق معيار الفحص الصيني GB8218-2003 بشهادة SGS، يغطي 88-2 من 12 إلى 220 فولت تيار متردد مع حد أقصى 250 فولت — نطاق المقابس والمفاتيح وامتدادات الكابلات للعمل المنزلي والتجاري الخفيف — مع تنبيه ضوئي وصوتي على السلك المشحون.',
		'pen2q' => 'كيف أستخدم 88-2 بشكل صحيح؟',
		'pen2a' => 'أمسك القلم من الجسم المعزول، وأبقِ إصبعك على القبعة المعدنية في الخلف، والمس الطرف بالموصل. جسدك هو مسار العودة: خلال نحو ثانيتين تعرض الشاشة الرقمية قيمة الجهد الحي ويؤكده تنبيه ضوئي وصوتي. دون تبديل النطاقات: لمس، قراءة، انتهى.',
		'pen3q' => 'هل يستطيع 88-2 أن يحل محل الملتيميتر؟',
		'pen3a' => 'لا. 88-2 يقرأ الجهد فقط: يعرض القيمة الحية، لكنه لا يقيس الاستمرارية أو المقاومة أو التيار، وغير مصنف للأعمال الصناعية عالية الجهد أو ثلاثية الأطوار. استخدمه مع الملتيميتر للتشخيص الكامل.',
		'pen4q' => 'هل يحمل 88-2 شهادات وهل يمكنني الطلب بالجملة؟',
		'pen4a' => 'نعم. الإنتاج يتبع GB8218-2003 مع أخذ العينات وفق GB8218-87 S-4، ورقم شهادة SGS مطبوع في ورقة المواصفات، والوحدة مطابقة لـ CE وRoHS مع ضمان 12 شهرًا. CHINYOO هو المصنع، لذا البيع بالجملة والعلامة OEM متاحان.',

		'dm6266q1' => 'ما أقصى تيار يقيسه مقياس المشبك DM6266F؟',
		'dm6266q1a' => 'حتى 1000 أمبير تيار متردد على مدّي 200 أمبير و1000 أمبير — يكفي لتغذية المحركات ولوحات التوزيع ومخرجات محولات التردد، ويُقاس دون فتح الدائرة.',
		'dm6266q2' => 'هل يقيس DM6266F التردد؟',
		'dm6266q2a' => 'نعم. يقيس التردد حتى 2000 هرتز، وهو ما يغطي مخرج معظم محولات التردد ويتيح التحقق من سرعة المحرك دون أداة ثانية.',
		'dm6266q3' => 'ما الفرق بين DM6266F وVC3268؟',
		'dm6266q3a' => 'VC3268 مشبك مضغوط بعدّاد 4000 رقم مع قياس التيار المستمر والسعة. DM6266F أبسط وأمتن: 1000 أمبير تيار متردد، حد أقصى للمقاومة 2000 ميجا أوم، ومدى تردد على شاشة 1999 رقم.',
		'dm6266q4' => 'هل يمكن شراء DM6266F بالجملة أو بعلامتي الخاصة؟',
		'dm6266q4a' => 'نعم — CHINYOO هي المصنع في ونتشو. نوفر DM6266F للجملة وبرامج OEM/ODM مع علامة مخصصة وتغليف ووثائق CE/RoHS. أرسل لنا الكمية المستهدفة لتصلك عروض الأسعار.',
		'mvd765q1' => 'ماذا يفعل قلم اختبار الجهد من سلسلة MVD765؟',
		'mvd765q1a' => 'يقرأ الجهد الفعلي من 12 إلى 220 فولت تيار متردد بحد أقصى 250 فولت، ويعرض القيمة على شاشة رقمية بينما يؤكد التنبيه الصوتي والضوئي السلك الحي. مصنوع وفق GB8218-2003 ومعتمد من SGS.',
		'mvd765q2' => 'ما الفرق بين MVD765A وB وC وD؟',
		'mvd765q2a' => 'المواصفات الكهربائية والشهادات متطابقة. الفرق في التغليف: علبة تجزئة من 8 قطع، وعلبة عرض من 20 قطعة، وبطاقة بليستر — عائلة واحدة من الأقلام تغطي قنوات بيع مختلفة.',
		'mvd765q3' => 'هل يمكن أن يحل MVD765 محل جهاز القياس المتعدد؟',
		'mvd765q3a' => 'لا. MVD765 يقيس الجهد فقط، دون مديات للاستمرارية أو المقاومة، ويبقى ضمن نطاق الاستخدام المنزلي والتجاري الخفيف 12-220 فولت. للفحص الكامل استخدمه مع جهاز قياس متعدد.',
		'mvd765q4' => 'هل يمكن شراء سلسلة MVD765 بالجملة أو بعلامتي الخاصة؟',
		'mvd765q4a' => 'نعم — CHINYOO هي المصنع. نوفر سلسلة MVD765 للجملة وبرامج OEM/ODM مع علامة مخصصة وتغليف ووثائق CE/RoHS، بما في ذلك أوراق GB8218 وSGS.',

		'td1q' => 'كيف يقيس المقياس المتعدد الحرارة؟',
		'td1a' => 'عبر مجس حراري من النوع K يُثبَّت في مقبس مخصص عليه رمز ترمومتر. يلتقي معدنان مختلفان عند طرف المجس ويولّدان جهداً صغيراً يتغيّر مع الحرارة؛ يقرأ المقياس هذا الجهد ويحوّله إلى قراءة على الشاشة. الأجهزة الحديثة تجري تعويض الوصلة الباردة داخلياً، فالقراءة تعبّر عن الطرف لا عن المقبس.',
		'td2q' => 'ما نطاق درجات الحرارة الذي يقيسه المقياس المتعدد المزوّد بمجس حراري؟',
		'td2a' => 'معظم أجهزتنا المزوّدة بقياس الحرارة تقيس من -20 درجة مئوية إلى 1000 درجة بدقة تتراوح تقريباً بين ±2% و±3%، ما يغطي فتحات التكييف والمبخّرات، وفحص المحركات والمحامل، وإصلاح الأجهزة المنزلية وسخّانات الماء. في معظم الموديلات، المجس الحراري من النوع K مشمول في العلبة.',
		'td3q' => 'أي مقاييس CHINYOO تشمل قياس الحرارة؟',
		'td3a' => 'خط منتجاتنا المزوّد بقياس الحرارة يبدأ من موديلات الدخول DT838 وDM102، مروراً بـ MY62 وMY64 وVC17B، وصولاً إلى مقاييس الدقة الأعلى VC9805 وVC9808 — 15 موديلاً في المجموع. إذا كنت تشتري لفريق، أرسل لنا درجات الحرارة التي تقيسها في أسبوع عادي وسنطابق المقياس ونوع المجس مع العمل.',
		'td4q' => 'هل يمكن شراء مقياس متعدد بقياس الحرارة بالجملة أو بعلامة تجارية خاصة؟',
		'td4a' => 'نعم — CHINYOO هي المصنع في ونزو. نوفر مقاييس متعددة بقياس الحرارة للبيع بالجملة وبرامج OEM/ODM بعلامتك التجارية وتغليفك ووثائق CE/RoHS. وتخرج عينة قبل أي طلب إنتاج.',
		'vc9805q1q' => 'ما الذي يميّز VC9805 عن المقياس المتعدد الأساسي بعدّات 1999؟',
		'vc9805q1a' => 'VC9805 مقياس مكتبي كامل الحجم بشاشة مضيئة من الخلف بعدّات 4000، وكشف جهد لاتلامسي، ومدى سعة حتى 400 µF، ومدى تردد حتى 4 MHz، واختبار كسب الترانزستور hFE. أما المقياس الأساسي بعدّات 1999 فيقرأ الجهد والمقاومة والتيار فقط؛ يضيف VC9805 الوظائف التي يستخدمها فنيو الإصلاح يومياً.',
		'vc9805q2q' => 'هل تخبرني وظيفة NCV ما إذا كان السلك مشحوناً؟',
		'vc9805q2a' => 'نعم. تكشف وظيفة الجهد اللاتلامسي NCV المجال الكهربائي المستحث حول الموصل، فتتمكن من التأكد من أن الموصل أو الطرف مشحون دون لمس المعدن العاري. ومع ذلك تحقق دائماً من الجهد بقراءة تلامسية قبل أن تعتمد على النتيجة.',
		'vc9805q3q' => 'ما هي فحوصات الأمان والجودة على جهاز VC9805؟',
		'vc9805q3a' => 'كل جهاز VC9805 يخضع لفحص معايرة وفحص وظائف في مصنعنا في ونزو قبل التغليف، وهو متوافق مع CE وRoHS، ومزوّد بحماية من الحمل الزائد على جميع النطاقات، ومشمول بضمان لمدة 12 شهراً مع دعم مهندسين خلال 24 ساعة.',
		'vc9805q4q' => 'هل يمكن بيع VC9805 تحت علامتنا التجارية الخاصة؟',
		'vc9805q4a' => 'نعم. نوفّر لـ VC9805 طباعة العلامة التجارية والتغليف المخصصين (OEM). اطلب عينة أولاً، وأخبرنا بالكمية والوجهة، وسيؤكد فريقنا مدة التسليم وسعر القطعة الواحدة.',
		'st105q1q' => 'ما هي زاوية dwell ولماذا تحتاج إلى قياسها؟',
		'st105q1a' => 'في الموزّع ذي نقاط التلامس الميكانيكية، تعبّر زاوية dwell عن المدة التي تبقى خلالها النقاط مغلقة، وتُقاس بدرجات دوران الموزّع. إذا قلت الزاوية ضعفت شرارة الإشعال، وإذا زادت تعرّضت النقاط للتآكل. وضبط dwell على القيمة الواردة في دليل الصيانة جزء أساسي من ضبط محرك الإشعال بنقاط التلامس والمكثّف.',
		'st105q2q' => 'ما المركبات التي صُمّم من أجلها ST105؟',
		'st105q2a' => 'صُمّم ST105 لمحركات البنزين المزوّدة بموزّع وإشعال بنقاط التلامس: السيارات الكلاسيكية، والدراجات النارية الأقدم، وأعمال المحركات الصغيرة، إضافة إلى تدريس إلكترونيات السيارات. ومديات عدد الدورات (RPM) وزاوية dwell فيه مضبوطة لمحركات 4 و6 و8 أسطوانات. أما المركبات الحديثة ذات الإشعال الإلكتروني فلا تُظهر هذه الإشارات للقياس.',
		'st105q3q' => 'هل يقيس ST105 التيار المتردد (AC)؟',
		'st105q3a' => 'لا. نطاقات التيار في الجهاز مخصصة للتيار المستمر (DC) فقط، من 200 مللي أمبير إلى 10 أمبير. ويقيس الجهد المتردد حتى 750 فولت، ويقرأ أيضاً المقاومة والسعة، لكن لا يوجد نطاق لتيار متردد ولا إضاءة خلفية للشاشة.',
		'st105q4q' => 'كيف أتحقق من صحة قراءات عدد الدورات (RPM) وزاوية dwell؟',
		'st105q4a' => 'شغّل ST105 بجانب مقياس عدد دورات (tachometer) أو مقياس dwell سليم معروف على المحرك نفسه، وتأكد من تطابق القراءتين. ويوضح الدليل المطبوع المرفق في العلبة طريقة التوصيل لكل إعداد خاص بمحرك من 4 أو 6 أو 8 أسطوانات.',
		'bt168q1q' => 'ما البطاريات التي يمكن أن يفحصها جهاز BT-168؟',
		'bt168q1a' => 'يفحص BT-168 خلايا 1.5 فولت من الأنواع AAA وAA وC وD، وبطاريات الأزرار الصغيرة، بالإضافة إلى أنواع 9 فولت مثل 6F22 وPP3 وMN1604. وتُظهر التدريجة المطبوعة على الجهاز حدود مناطق جيد وضعيف واستبدال لعائلتي 1.5 فولت و9 فولت.',
		'bt168q2q' => 'لماذا قد تظهر البطارية بحالة جيدة على المقياس المتعدد وتفشل على هذا الجهاز؟',
		'bt168q2a' => 'يقيس المقياس المتعدد الخلية وهي في حالة سكون ودون حمل تقريباً، لذلك قد تظهر الخلية المستهلكة بجهد قريب من جهدها المقنّن بينما تنهار فوراً تحت التيار الذي يسحبه الجهاز المشغّل. يضع BT-168 حملاً على الخلية تماماً كما يفعل الجهاز، ولهذا يستطيع التمييز بين الخلايا الجيدة والضعيفة.',
		'bt168q3q' => 'ماذا تعني مناطق جيد وضعيف واستبدال؟',
		'bt168q3a' => 'بالنسبة لخلية 1.5 فولت: جيد من 1.28 إلى 1.5 فولت، وضعيف من 1.15 إلى 1.27 فولت، واستبدال عندما ينخفض الجهد إلى ما دون 1.14 فولت تقريباً. وبالنسبة لبطارية 9 فولت: جيد من 7.8 إلى 9 فولت، وضعيف من 6 إلى 7.7 فولت، واستبدال عندما ينخفض إلى ما دون 5.9 فولت تقريباً.',
		'bt168q4q' => 'هل يحتاج جهاز BT-168 إلى بطارية خاصة به؟',
		'bt168q4a' => 'لا. يغتذي الجهاز من البطارية قيد الاختبار نفسها، فلا توجد فيه بطارية خاصة يمكن أن تُفرَّغ أو تحتاج إلى استبدال. وهو ليس شاحناً ولا محللاً للسعة؛ بل يمنحك حكماً سريعاً فقط: جيد أو ضعيف أو استبدال، على المقاسات المنزلية القياسية.',
		'vc890q1q' => 'ما الفرق بين VC890D و VC890L؟',
		'vc890q1a' => 'فرق واحد: VC890L مزوّد بإضاءة خلفية لشاشة LCD، أما VC890D فلا. كل ما عداهما متطابق — عرض 1999 عدّة، والنطاقات والدقة نفسها، والهيكل والمجسّان والجراب وبطارية 9 فولت. ويتشاركان قطع الغيار والكرتون نفسه.',
		'vc890q2q' => 'ماذا يقيس VC890؟',
		'vc890q2a' => 'الجهد المستمر والمتردد من 200 ميلي فولت إلى 1000 فولت و 750 فولت، والتيار المستمر والمتردد من 2 ميلي أمبير إلى 10 أمبير، والمقاومة من 200 أوم إلى 200 ميغا أوم، والسعة من 20 نانو فاراد إلى 200 ميكرو فاراد، إضافة إلى اختبار الدايود، و hFE للترانزستور، وصوتي الاستمرارية، وتثبيت القراءة، وحماية من الحمل الزائد على كل النطاقات.',
		'vc890q3q' => 'كيف يُعبأ VC890 للتصدير؟',
		'vc890q3a' => 'كل جهاز في علبة ملونة مع البطارية مركّبة والمجسّين والجراب والدليل. أربعون قطعة في كرتون بمقاس 43.5 × 30.5 × 51 سم، بوزن إجمالي 16.4 كغم وصافٍ 15.4 كغم.',
		'vc890q4q' => 'هل يمكننا طلب VC890 بعلامتنا التجارية؟',
		'vc890q4a' => 'نعم. CHINYOO هو المصنع في ونزو — نوّرد VC890D و VC890L لبرامج الجملة والتصنيع بالعلامة الخاصة مع علامة وتعبئة ووثائق CE/RoHS مخصّصة. ونرسل عيّنة قبل أي أمر إنتاج.',
	
    'dt331q' => 'ما الفرق بين DT33B وDT33C وDT33D؟',
    'dt331a' => 'الوظيفة الثالثة فقط. يضيف DT33B اختبار بطاريات 1.5 فولت و9 فولت و12 فولت؛ ويضيف DT33C قياس الحرارة بالتلامس من -20 إلى 1000 درجة مئوية؛ ويضيف DT33D خرج موجة مربعة. الهيكل وشاشة 1999 عدّة ونطاقات الجهد المستمر والمتردد متطابقة في الثلاثة.',
    'dt332q' => 'ما الذي تقيسه سلسلة DT33؟',
    'dt332a' => 'الجهد المستمر من 200 مللي فولت إلى 500 فولت، والجهد المتردد من 200 فولت إلى 500 فولت، والتيار المستمر من 200 أو 2000 ميكروأمبير حتى 10 أمبير، والمقاومة من 200 أوم إلى 20 أو 200 ميجاأوم، إضافة إلى اختبار الدايود وصافرة الاستمرارية وتثبيت القراءة والإضاءة الخلفية. الطرازات الثلاثة بفئة CAT I 600V وCAT II 300V.',
    'dt333q' => 'أي طراز من DT33 يلائم الموزّع؟',
    'dt333a' => 'طابق الوظيفة المضافة مع قناتك. متاجر التجزئة والأدوات تبيع DT33B لأن اختبار البطاريات يُعرض أمام الزبون في لحظات. وموزّعو التكييف والتبريد يبيعون DT33C لنطاق الحرارة. وموردو الإلكترونيات والمدارس يشترون DT33D لتتبّع الإشارة.',
    'dt334q' => 'هل يمكن طلب سلسلة DT33 بعلامتنا التجارية؟',
    'dt334a' => 'نعم. CHINYOO هي المصنع في ونتشو. نورّد DT33B وDT33C وDT33D بالجملة وببرامج OEM/ODM مع علامة وتغليف ونطاقات مخصصة. الطرازات الثلاثة تُعبّأ 60 قطعة في الكرتون بمقاس 30.8 × 28.3 × 62 سم.',
		'capg1q' => 'ما الفرق بين فحص المكثف بمقياس متعدد وبمقياس ESR؟',
		'capg1a' => 'يقيس المقياس المتعدد السعة، فيخبرك إن كانت القيمة قد انحرفت عن العلامة المطبوعة. أما مقياس ESR فيقيس المقاومة المكافئة على التوالي، وهي ما يفشل فعليًا أولًا في المكثفات الإلكتروليتية. فقد يقرأ مكثف السعة الصحيحة ومع ذلك تكون مقاومته ESR عالية بما يكفي لتعطيل الدائرة، لذا تجيب الأداتان عن سؤالين مختلفين.',
		'capg2q' => 'هل يستطيع المقياس المتعدد فحص مكثف دون نزعه من اللوحة؟',
		'capg2a' => 'سيعطيك قراءة، لكنها ليست قراءة يمكنك الاعتماد عليها. فكل ما هو موصول على التوازي مع المكثف يضاف إلى القياس، وأي مسار تفريغ يجعل القيمة تنحرف أمام عينيك. وفك أحد طرفيه باللحام هو السبيل الوحيد للحصول على رقم يعكس المكثف وحده.',
		'capg3q' => 'كيف أفرّغ شحنة المكثف بأمان قبل فحصه؟',
		'capg3a' => 'افصل الطاقة، ثم اربط طرفي المكثف بمقاومة من بضعة كيلو أوم بدلًا من مفك البراغي. فمفك البراغي يسحب قوسًا كهربائيًا قد يتلف المكثف واللوحة. وتحتفظ المكثفات الإلكتروليتية الكبيرة بشحنة خطيرة لدقائق بعد نزع الطاقة، لذا قِس الجهد عبر أطرافها قبل أن تلمس أي شيء.',
		'capg4q' => 'ما أنواع المكثفات التي يستطيع المقياس المتعدد فحصها؟',
		'capg4a' => 'أي مكثف داخل نطاق السعة للجهاز، وهو في مقاييسنا يمتد من 4 nF إلى 4 mF على DT6222 وحتى 40 mF على XT802. أما الأجزاء السيراميكية دون بضعة نانوفاراد فتقع قرب الحد الأدنى لدقة المقياس المحمول، والمكثفات الإلكتروليتية الأعلى من سقف النطاق تحتاج إلى أداة مخصصة.',
		'bvcg1q' => 'ما الجهد الذي يمثّل شحنًا بنسبة 100% في بطارية سيارة 12 V؟',
		'bvcg1a' => '12.65 V أو أكثر في حالة السكون. ويأتي المقياس دون ذلك عند 12.45 V لنحو 75%، و12.24 V لنحو 50%، و12.06 V لنحو 25%، و11.89 V أو أقل للبطارية الفارغة. خُذ القراءة والمحرك وكل الأحمال متوقفة، واترك البطارية تستقر قبل القياس.',
		'bvcg2q' => 'هل ينبغي أن أفحص بطارية السيارة والمحرك يعمل؟',
		'bvcg2a' => 'نعم، لأن القراءات الثلاث تجيب عن ثلاثة أسئلة مختلفة. فجهد السكون يعطي حالة الشحن، وجهد التدوير يُظهر ما إذا كانت البطارية قادرة على توفير تيار بدء التشغيل، والقراءة والمحرك يعمل تُظهر ما إذا كان المولّد يشحن — ونظام الشحن السليم يحافظ على نحو 13.5 V إلى 14.5 V عند السرعة الخاملة.',
		'bvcg3q' => 'هل يعني جهد 12.2 V أن بطارية السيارة تالفة؟',
		'bvcg3a' => 'إنها بطارية مفرغة وليست بالضرورة تالفة. فـ 12.24 V يقابل نحو 50% من حالة الشحن، لذا تحتاج البطارية إلى شحن قبل أن تحكم عليها. اشحنها، واتركها تستقر، وقِس مرة أخرى: فإذا عادت إلى 12.65 V أو أكثر وصمدت، فالبطارية صالحة للخدمة؛ وإذا هبطت سريعًا من جديد، فالبطارية أو نظام الشحن يحتاج إلى عناية.',
		'bvcg4q' => 'هل تؤثر درجة الحرارة على القراءة التي أحصل عليها من بطارية السيارة؟',
		'bvcg4a' => 'نعم. فالبطارية الباردة تقرأ أقل قليلًا لنفس حالة الشحن وتقبل الشحن ببطء أكبر، ولهذا كثيرًا ما تفشل البطارية الحدّية في الصيف في أول صباح بارد. قارن القراءات المأخوذة عند درجات حرارة متشابهة، وتعامل مع البطارية التي تقرأ دون 12.45 V في الطقس البارد كبطارية تحتاج إلى شحن وإعادة فحص لا إلى الحكم عليها بالعطب.',
		'fuseg1q' => 'ما الفرق بين فحص المصهر بمقياس متعدد وبمصباح اختبار؟',
		'fuseg1a' => 'يُظهر مصباح الاختبار وجود الجهد أو غيابه ويحتاج إلى دائرة مشغّلة؛ أما المقياس المتعدد فيقيس الجهد والاستمرارية معًا، فيصلح أيضًا مع الدائرة المعزولة. وبالنسبة لمصهر شفرة في صندوق مصهرات حيّ يكون مصباح الاختبار أسرع، أما بالنسبة لمصهر سبق أن سحبته فتُعدّ وظيفة الاستمرارية في المقياس المتعدد الإجابة الأكثر حسمًا.',
		'fuseg2q' => 'كيف أفحص المصهر بمقياس متعدد وهو ما زال في حامله؟',
		'fuseg2a' => 'اضبط المقياس على جهد التيار المستمر DC، وصِل المجس الأسود بأرضي معروف والمس المجس الأحمر بكل من نقطتي الفحص أعلى المصهر بالتتابع. فالمصهر السليم يُظهر الجهد نفسه عند النقطتين؛ أما المحترق فيُظهر جهد التغذية عند إحداهما ولا شيء عند الأخرى. ويعمل ذلك لأن نقطتي الفحص تقعان على جانبي العنصر.',
		'fuseg3q' => 'لماذا يفصل قاطع الدائرة فورًا بعد إعادة ضبطه؟',
		'fuseg3a' => 'القاطع الذي يفصل مجددًا في الحال يُبلّغ عن عطل في الدائرة لا عن فشل في نفسه. افصل الأحمال واحدًا تلو الآخر وأعد الضبط بين كل محاولة لتحدد الفرع الذي يحمل العطل، وافحص عن قصر بين الحي والمحايد أو عطل بين الحي والأرضي. فإعادة الضبط مرارًا في عطل حي هي السبيل إلى تلف القواطع والأسلاك.',
		'fuseg4q' => 'هل يمكنني فحص مصهر أو قاطع والدائرة حية؟',
		'fuseg4a' => 'يمكنك قياس الجهد عند المصهر والدائرة حية، وهي الطريقة المعتادة لفحص مصهر شفرة في مكانه. أما اختبارات الاستمرارية والمقاومة فيجب إجراؤها والدائرة معزولة والمصهر منزوع، لأن المقياس يوفّر تيار اختباره الخاص، وأي مسار على التوازي في دائرة حية يجعل النتيجة بلا معنى. ولا تعمل أبدًا على قاطع والدائرة موصولة بالطاقة.',
		'ghostg1q' => 'هل يعني الجهد الوهمي أن الأسلاك معيبة؟',
		'ghostg1a' => 'لا. فالاقتران السعوي بين الموصلات المتوازية أمر طبيعي في التركيب العامل، وهو الجهاز يُبلّغ عن مجال حقيقي لا عن وجود عيب. ولا يصبح الجهد الوهمي خطرًا إلا إذا قرأ أحدهم إشارة لاتلامسية كدليل على أن موصلًا حيّ، أو قرأ صمت الكاشف كدليل على أن موصلًا ميت.',
		'ghostg2q' => 'لماذا يعطي الكاشف نفسه نتائج مختلفة لشخصين مختلفين؟',
		'ghostg2a' => 'يحتاج الكاشف اللاتلامسي إلى مسار عودة للتيار الصغير الذي يستشعره، وهذا المسار يمر عبر جسم المستخدم إلى ما حوله. فإمساك جسم الجهاز بإحكام يقترن بشكل أفضل من لمسه بطرف الإصبع، بينما تؤدي القفازات العازلة والأحذية العازلة والأرضية العازلة كلها إلى تقليل المسار وجعل الجهاز يبدو أقل حساسية. الكاشف يتصرف بثبات؛ أما الظروف فليست ثابتة.',
		'ghostg3q' => 'هل يمكن أن يفوّت الكاشف اللاتلامسي موصلًا حيًّا؟',
		'ghostg3a' => 'نعم، وهذا هو الفشل الخطير. فالأنبوب المعدني المؤرَّض أو الدرع المعدني يضع سعة كبيرة بين الموصل الحي والأرضي، فيظهر قليل جدًا من الجهد حيث يستطيع الكاشف استشعاره؛ وللعزل السميك تأثير مماثل. والبطارية الضعيفة تقلل الحساسية تدريجيًا ودون إنذار، فاستبدلها قبل أن تتدهور لا بعد ذلك.',
		'ghostg4q' => 'ما التسلسل الصحيح لإثبات أن الدائرة معزولة؟',
		'ghostg4a' => 'أثبت عمل الأداة على مصدر معروف بأنه حيّ، ثم افحص الموصلات التي أنت على وشك العمل عليها، ثم أثبت عمل الأداة مرة أخرى على المصدر المعروف بأنه حيّ. والقياس الذي يثبت العزل هو قياس جهد تلامسي على الموصلات نفسها، يُجرى بمقياس مصنّف لفئة الموقع وجهدها. أما الإشارة اللاتلامسية فمحلها بداية التسلسل لا نهايته.',
		// الدفعة 5 (2026-10-15): قراءة الاستمرارية / مقبس التيار / التيار الطفيلي.
	'contg1q' => 'ما المقاومة التي يعنيها صفير الاستمرارية فعلاً؟',
	'contg1a' => 'الصفير يعني أن المقاومة بين المجسين أقل من عتبة مدمجة في الجهاز، وليس أنها صفر. على XT802 نطاق الاستمرارية مطبوع على اللوحة 0.1~50 ohms، لذا وصلة تقيس 30 ohms ستصفّر على ذلك الجهاز. الجهاز بعتبة 10 ohms يبقى صامتاً على الوصلة نفسها. لا أحد منهما خاطئ؛ إنهما يجيبان عن سؤالين مختلفين قليلاً.',
	'contg2q' => 'لماذا يصفّر جهازي والمجسان متباعدان؟',
	'contg2a' => 'إما أن المجسين يلامسان شيئاً لم تلاحظه، أو أن سلك الاختبار نفسه متقطع. المس طرفي المجسين معاً دون أي شيء آخر في الدائرة واقرأ القيمة: الزوج الجيد يقرأ أقل من 0.2 ohms. أي قيمة أعلى، أو قراءة تقفز، تعني أنك تقيس السلك لا الوصلة، ويجب استبدال السلك قبل الوثوق بأي قراءة.',
	'contg3q' => 'هل أستخدم وضع الاستمرارية أم نطاق المقاومة؟',
	'contg3a' => 'وضع الاستمرارية للسرعة على مسارات الكابلات الطويلة، حيث السؤال الوحيد هو ما إذا كان الموصل متصلاً من طرف إلى طرف. عندما تهم المقاومة الفعلية، انتقل إلى نطاق المقاومة: على DT6222 يغطي ذلك 400 ohms~40 megohms بدقة ±1.2%، وهو تحليل كافٍ لمراقبة تدهور تلامس من 0.05 ohms إلى 0.5 ohms عبر عمليات صيانة متتالية.',
	'contg4q' => 'لماذا يصفّر الدايود المقصور في كل من الاستمرارية ووضع اختبار الدايود؟',
	'contg4a' => 'لأن الوصلة المقصورة توصل في كلا الاتجاهين، فترى الاستمرارية مساراً مغلقاً ويرى اختبار الدايود هبوطاً أمامياً قرب الصفر. وضع اختبار الدايود هو الوظيفة التي تفصل بينهما: الوصلة السيليزية السليمة تقرأ نحو 0.3~0.7 volts أمامياً ودائرة مفتوحة عكسياً، والقطعة التي تقرأ قرب الصفر في الاتجاهين قد فشلت قصراً. استخدم وضع الدايود متى احتوت الدائرة على شبه موصل.',
	'jackg1q' => 'لماذا يُقرأ التيار نفسه بشكل مختلف على مدخل 10 A ومدخل mA؟',
	'jackg1a' => 'لأن المدخلين يصلان الجهاز بمقاومتي تحويل (شنت) مختلفتين. مدخل 10 A يستخدم شنتاً ثقيلاً منخفض المقاومة يحمل تياراً كبيراً؛ ومدخل mA يستخدم شنتاً أخف أعلى مقاومة يمنح تحليلاً أدق. القراءة تأتي من المدخل الذي يوجد فيه السلك الأحمر، لذا سلك متروك في مدخل 10 A أثناء قياس بضعة milliamps ينتج رقماً يهيمن عليه حد التحليل الأدنى لذلك النطاق.',
	'jackg2q' => 'ماذا يعني حد 10 seconds الأقصى على مدخل 10 A؟',
	'jackg2a' => 'إنه حد مدة التشغيل، وليس شكلاً إجرائياً. عشرة أمبير عبر الشنت تولّد حرارة، وداخل علبة محمولة باليد لا تجد تلك الحرارة منفذاً، لذا صُنّف المدخل لمدة 10 seconds ثم يحتاج إلى تبريد. الجهاز المتروك متصلاً على حمل 10 amp سينزاح مع سخونة الشنت وتبتعد القراءة عن الحقيقة قبل أن يحدث أي شيء مرئي للجهاز.',
	'jackg3q' => 'ما أصغر تيار يمكن لكل تصميم قياسه؟',
	'jackg3a' => 'على XT802 المدخل الوحيد 10 A موسوم من 20 milliamps إلى 10 amps، لذا تحت 20 milliamps تتوقف الشاشة عن كونها ذات معنى — تيار سكون 35 milliamp قابل للقياس هناك، أما 4 milliamp فلا. أما DT6222 فيضع الميكروأمبير والمليأمبير على مدخل خاص بهما محمي بمنصهر 400 milliamps، مع نطاقات 400/4000 microamp و40/200 milliamp بدقة ±1.4% على شاشة 4000-count.',
	'jackg4q' => 'هل يمكنني قياس التيار دون قطع الدائرة؟',
	'jackg4a' => 'ليس بجهاز متعدد القياسات، لأن قياس التيار يعمل بإدخال الجهاز في فجوة الدائرة. فوق أعلى نطاق تيار للجهاز، الأداة الصحيحة هي مقياس التيار الزاحف (الكلامب)، الذي يلتف حول الموصل ولا يقطعه أبداً. فتح دائرة 100 amp لإدخال جهاز خطر وليس قياساً، كما يمكن للكلامب أن يبقى متصلاً بلا حد بينما لا يستطيع مدخل 10 A ذلك.',
	'pdg1q' => 'كم مليأمبير من التيار الطفيلي يُعدّ طبيعياً؟',
	'pdg1a' => 'معظم المركبات تستقر بين 20 و50 milliamps بعد دخول كل الوحدات في وضع السكون. أقل من 20 milliamps طبيعي وعلى الجانب المنخفض، و50 إلى 80 milliamps حدّي ويستحق إعادة القياس بعد فترة سكون أطول، وفوق 80 milliamps سيُفرغ بطارية سليمة في أيام إلى أسابيع. فوق 1 amp تكون إحدى الوحدات مستيقظة أو مصباحاً ما زال مضاءً.',
	'pdg2q' => 'كم يجب أن أنتظر قبل أن تصبح القراءة ذات معنى؟',
	'pdg2a' => 'حتى تدخل المركبة في وضع السكون التام، وهو ما يتراوح بين عشرين دقيقة وساعة حسب الطراز. السيارة التي فُتحت للتو تسحب عدة أمبيرات، والقياس خلال تلك النافذة هو السبب الأكثر شيوعاً لتشخيص سيارة سليمة بأنها معطلة. ثبّت الجهاز، وأغلق كل شيء، واتركه لفترة السكون الكاملة التي تحددها الشركة المصنعة قبل قراءة أي شيء إطلاقاً.',
	'pdg3q' => 'أي نطاق تيار أستخدم لاختبار التيار الطفيلي؟',
	'pdg3a' => 'نطاق 40 milliamp على جهاز يمتلكه. أربعون مليأمبير قريبة من أعلى ذلك النطاق، لذا تستخدم القراءة الطبيعية معظم المقياس ويَسهُل الوثوق بها، والخانة الأخيرة 10 microamps — وهي تحل الفرق بين 20 و25 milliamps. على مدخل 10 A يعيد القياس نفسه رقماً يبدو معقولاً يخفي كل شيء في النطاق الذي تحاول قراءته.',
	'pdg4q' => 'ماذا لو كان السحب يأتي ويذهب بدل أن يبقى ثابتاً؟',
	'pdg4a' => 'إذن السلوك المتقطع هو النتيجة لا الرقم. التسريبات المتقطعة غالباً وحدة تستيقظ بمؤقت، أو مصباح صندوق الأمتعة أو مصباح صندوق القفازات على مفتاح متهالك، أو مرحّل لا يتحرر بنظافة. ترك الجهاز متصلاً ومراقبة الشاشة لفترة أطول هي الطريقة الوحيدة لالتقاط أحدها، لذا أوقف الإطفاء التلقائي قبل أن تبدأ.',
	'priceg1q' => 'لماذا يمكن أن يختلف سعر مقياسين متعددين متطابقين في المظهر بعشرة أضعاف؟',
	'priceg1a' => 'لأن الفرق يكمن في أجزاء لا تُرى من خارج العلبة. المصهر في مقبس التيار، وشبكة الحماية خلف المقابس، ونوع شريحة القياس، وفئة تفاوت مقاومات المرجع، وما إذا كان يُحفظ سجل معايرة لكل وحدة — كلها بنود تكلفة، ولا يظهر أي منها على الرف. ويشمل السعر كذلك القناة: أجرة الشحن للتصدير، والرسوم الجمركية، وطبقتا هامش ربح تقعان بين المصنع ورف المتجر.',
	'priceg2q' => 'إذا بدا عرض السعر رخيصًا بشكل مريب، عن أي بند نسأل أولًا؟',
	'priceg2a' => 'عن المصهر في مقبس التيار. المصهر الخزفي ذو القدرة العالية على القطع، والمقنن للنطاق الكامل، تكلفة حقيقية لكل وحدة، واستبداله بمصهر زجاجي أو ترك أحد المقابس بلا مصهر هو أسهل طريق لتخفيض قائمة المواد. التوفير صغير؛ أما النتيجة فأن اختيار نطاق خاطئ واحد على دائرة تحت جهد يحوّل القياس إلى قوس داخل العلبة.',
	'priceg3q' => 'هل تنخفض تكلفة الوحدة فعلاً عند زيادة كمية الطلب؟',
	'priceg3a' => 'نعم، ولسببين مختلفين. الأول هو القدرة التفاوضية المعتادة على المكونات. والثاني هو العدد: العلبة، والطباعة الحريرية، ومطابقة اللون، والملصق المخصص تحمل تكلفة تُدفع مرة واحدة وتُوزَّع على كامل الدفعة. عند الكميات الصغيرة تهيمن هذه التكلفة الواحدة على سعر الوحدة، وعند بضعة آلاف وحدة تذوب داخل سعر المكونات.',
	'priceg4q' => 'هل يمكن أن يحتوي مقياسان متباعدان جدًا في السعر على اللوحة نفسها؟',
	'priceg4a' => 'نعم. عدد قليل من مكاسب الدخل الأمامية للقياس يخدم حصة كبيرة جدًا من أجهزة العالم، لذا يمكن أن يتشارك مقياسان متباعدان في السعر المُحوِّل نفسه فعلاً. ما يختلف هو ما يحيط به: شبكة الحماية، وعناصر المرجع، والعلبة، والشاشة، ونظام المعايرة. ولهذا فإن مقارنة الشرائح ليست طريقة مفيدة لمقارنة المقاييس.',
	'gfig1q' => 'هل GFI هو نفسه GFCI؟',
	'gfig1a' => 'نعم. يشير المصطلحان إلى الجهاز نفسه؛ والصيغة الأقصر أكثر شيوعًا في بعض المناطق وعلى بعض ملصقات المنتجات. كلاهما يقارن التيار الخارج على الموصل الطوري بالتيار العائد على الموصل المتعادل، وكلاهما يقطع الدائرة عندما يتجاوز الفرق الحد المقرر.',
	'gfig2q' => 'عند أي تيار يفصل جهاز GFCI؟',
	'gfig2a' => 'وفق UL 943 يفصل جهاز الفئة A عند 5 ملي أمبير زائد أو ناقص 1 ملي أمبير، وعليه أن يفعل ذلك خلال زمن محدد. والحد منخفض إلى هذا القدر لأن الخطر المقصود هو التيار المار في جسم إنسان، وليس التيار المار في موصل.',
	'gfig3q' => 'هل يكفي مقياس مقبس لإثبات أن GFCI يعمل؟',
	'gfig3a' => 'لا. المقياس الذي فيه زر اختبار GFCI يثبت أن الجهاز يفصل عند محاكاة عطل؛ لكنه لا يقيس التيار الذي فصل عنده ولا الزمن الذي استغرقه. الجهاز الذي يفصل عند 8 ملي أمبير والذي يفصل عند 5 يجتازان هذا الفحص بالتساوي. وتأكيد الحد يحتاج جهازًا يقيس تيار الفصل.',
	'gfig4q' => 'أين يُستخدم كل مصطلح؟',
	'gfig4a' => 'GFCI هو مصطلح الأكواد والملصقات في أمريكا الشمالية، ويظهر GFI على حصة كبيرة من الأجهزة المباعة عبر قنوات التجزئة هناك. وفي المملكة المتحدة وأوروبا تظهر الوظيفة الوقائية نفسها تحت مصطلح جهاز التيار المتبقي، لذا على الموزع الذي يطابق كتالوجه مع سوق أن يقرأ المعيار المكتوب على الجهاز لا الاختصار المكتوب على العلبة.',
	'elecg1q' => 'أي مواصفة ينبغي أن ينظر إليها الكهربائي أولًا في المقياس المتعدد؟',
	'elecg1a' => 'حد الاستمرارية. فحص الاستمرارية هو القياس الأكثر تكرارًا في الموقع، وحد الصفير يختلف بين الطُرز: مقياس يصفر حتى 50 أوم سيمرر وصلة يرفضها مقياس آخر حده 10 أوم. وقد يختلف فنيان بمقياسين حول الموصل نفسه ويكون كل منهما يقرأ أداته قراءة صحيحة.',
	'elecg2q' => 'لماذا يهم مقبس التيار أكثر من نطاق التيار؟',
	'elecg2a' => 'لأن التيار يُقاس على التوالي، فكل ملي أمبير يمر عبر الجهاز، والمقبس هو ما يحدد من أي مُشتِّق تُقرأ القيمة. المقبس الواحد 10 A يقيس ابتداءً من 20 ملي أمبير؛ أما الجهاز الذي يفصل الميكرو أمبير والملي أمبير إلى مقبس مستقل مزوّد بمصهر فيستطيع قياس تيار سكون لا يراه مدخل 10 A إطلاقًا.',
	'elecg3q' => 'كيف أميّز مقياسًا جيدًا من سيئ قبل الشراء؟',
	'elecg3a' => 'اجمع طرفي المجسّين معًا واقرأ الناتج. الزوج الجيد يعطي أقل من 0.2 أوم، وهذا الرقم هو أرضية كل ما سيقيسه الجهاز بعده. والمقياس الذي يعطي مجسّاه أومًا واحدًا لا يستطيع التمييز بين وصلة جيدة ووصلة حدّية، لأن الاثنتين تقعان داخل خطئه هو.',
	'elecg4q' => 'هل يكفي كاشف الجهد بدون تلامس لتأكيد أن الدائرة مطفأة؟',
	'elecg4a' => 'لا. فهو يستجيب للمجال الكهربائي حول الموصل، ولذلك قد يعمل بفعل كبل مجاور تحت جهد، أو بفعل اقتران سعوي عبر جدار، أو بفعل موصل غير متصل بأي شيء. اعتبره تمريرة أولى تدلّك على موضع المجسّين؛ أما التأكيد فيجب أن يأتي من قياس بالتلامس على مصدر سليم معروف ثم على الموصل نفسه.',

);
}